"""Original multivariable candidates; all statements and derivations authored here."""
from common import *
x,y,z,t=s.symbols('x y z t',real=True)
reg=Registry('multivariable');register=reg.register
catalog=reg.catalog;build=reg.build;verify=reg.verify;all_candidates=reg.all_candidates

@register('competing-parabolic-ridges','multiscale-cluster-set','Two terms separately attain sharp bounds, but their maximizing scales are incompatible; establish a product estimate before constructing paths.','Unlike anisotropic integrability, this asks for the full limiting upper value of competing scales; bounding each term separately gives the wrong sum.',[{'a':a,'b':b} for a,b in [(1,2),(3,1),(-1,4),(2,3),(-2,-5),(6,1),(3,5),(5,4),(2,7),(7,-3)]],'incompatible-scales-and-cluster-paths',('multivariable limits','sharp inequalities'))
def ridges(a,b):
 A=x*x*y/(x**4+y*y);B=x*y*y/(x*x+y**4);answer=max(abs(a),abs(b))/2
 u=s.symbols('u',positive=True)
 first=s.limit(A.subs({x:u,y:s.sign(a)*u*u}),u,0);second=s.limit(B.subs({x:u,y:s.sign(a)*u*u}),u,0)
 third=s.limit(A.subs({x:s.sign(b)*u*u,y:u}),u,0);fourth=s.limit(B.subs({x:s.sign(b)*u*u,y:u}),u,0)
 return item(r'f(x,y)=\frac{'+L(a)+r'x^2y}{x^4+y^2}+\frac{'+L(b)+r'xy^2}{x^2+y^4}\quad((x,y)\ne(0,0)).'+T('Find ')+r'\limsup_{(x,y)\to(0,0)}f(x,y).',answer,[((abs(a)+abs(b))/2,'add incompatible individual maxima'),(s.sqrt(a*a+b*b)/2,'assume simultaneous circular tradeoff'),(min(abs(a),abs(b))/2,'select the smaller ridge'),(max(abs(a),abs(b)),'omit the sharp factor one half'),(R(0),'check only straight-line paths'),((a+b)/2,'ignore signs and incompatible scales')],[T('Denote the two fractions without their numerical coefficients by A and B. The square inequalities give ')+r'|A|\le\frac12,quad |B|\le\frac12,quad |AB|\le|xy|.',T('Consequently the smaller of their magnitudes tends to zero. Therefore ')+r'\limsup f\le\frac12\max\{'+L(abs(a))+','+L(abs(b))+r'\}.',T('Along ')+r'y=\operatorname{sgn}('+L(a)+r')x^2,quad x>0,'+T(' the first contribution tends to ')+L(abs(a)/2)+T(' and the second vanishes. Along ')+r'x=\operatorname{sgn}('+L(b)+r')y^2,quad y>0,'+T(' the roles reverse. The larger bound is attained as a path limit.')],[check('first parabolic path leading ridge',first,s.sign(a)/2),check('first path suppresses second ridge',second,0),check('second path suppresses first ridge',third,0),check('second path leading ridge',fourth,s.sign(b)/2),check('product denominator excess',(x**4+y*y)*(x*x+y**4)-x*x*y*y,x**6+x**4*y**4+y**6)],['The displayed denominators are positive away from the origin. The sign function in the solution is plus or minus one according to its nonzero argument.'],['For each term, twice the numerator magnitude is bounded by the denominator by a square. The denominator of the product is at least x squared times y squared, proving |AB|<=|xy|, including axes by continuity. Thus min(|A|,|B|)<=sqrt(|xy|), and |aA+bB|<=max(|a|,|b|)/2+min(|a|,|b|)sqrt(|xy|). The two explicit paths prove sharpness.'],'incompatible-parabolic-ridges-sharp-limsup')

@register('positive-matrix-cone-integral','positive-matrix-Cholesky-cone','Resolve a positive-definite matrix domain with a nonlinear triangular factorization, then combine its nonconstant Jacobian with Gaussian and gamma moments.','Not a Gaussian moment on all of Euclidean space: the positivity cone and determinant weight require a nonlinear domain parametrization.',[{'p':str(p),'a':a,'b':b,'c':c} for p,a,b,c in [(R(-1,2),2,2,1),(0,2,3,1),(R(1,2),2,3,1),(1,3,2,1),(R(3,2),3,3,1),(2,2,4,1),(R(5,2),3,4,2),(3,4,3,2),(R(7,2),4,4,1),(4,3,5,2)]],'Cholesky-domain-and-congruence-Jacobian',('positive definite matrices','Gaussian integrals','gamma integral'))
def cone(p,a,b,c):
 det=a*b-c*c;answer=s.sqrt(s.pi)*s.gamma(p+1)*s.gamma(p+R(3,2))/det**(p+R(3,2))
 u,v,w=s.symbols('u v w',positive=True);mapping=s.Matrix([u*u,v*v+w*w,u*v]);jac=mapping.jacobian([u,v,w]).det()
 # Independent route: z=sqrt(xy)r, with beta angular moment and separate gammas
 # for the identity precision matrix. Duplication relates this to Cholesky.
 other=s.gamma(p+R(3,2))**2*s.gamma(R(1,2))*s.gamma(p+1)/s.gamma(p+R(3,2))
 return item(T('Let ')+r'K=\begin{pmatrix}'+L(a)+'&'+L(c)+r'\\'+L(c)+'&'+L(b)+r'\end{pmatrix},\quad\mathcal P=\{(x,y,z):x>0, xy-z^2>0\}.'+T('Evaluate ')+r'\iiint_{\mathcal P}(xy-z^2)^{'+L(p)+r'}e^{-('+L(a)+r'x+'+L(2*c)+r'z+'+L(b)+r'y)}\,\mathrm dx\,\mathrm dy\,\mathrm dz.'+T('Here ')+r'\Gamma(v)=\int_0^\infty u^{v-1}e^{-u}\,\mathrm du\quad(v>0).',answer,[(answer*det**R(1,2),'use a two-dimensional instead of three-dimensional congruence Jacobian'),(answer/det**R(1,2),'add one excess determinant half-power'),(answer*2,'double the off-diagonal matrix coordinate'),(answer/2,'restrict the Cholesky off-diagonal coordinate to one sign'),(s.sqrt(s.pi)*s.gamma(p+1)**2/det**(p+R(3,2)),'omit one power of the first diagonal Cholesky coordinate')],[T('Write the symmetric matrix as ')+r'M=\begin{pmatrix}x&z\\z&y\end{pmatrix}=LL^{\mathsf T},\quad L=\begin{pmatrix}u&0\\v&w\end{pmatrix},\quad u,w>0, v\in\mathbb R.',r'\det M=u^2w^2,qquad \left|\frac{\partial(x,y,z)}{\partial(u,v,w)}\right|=4u^2w.',T('First take K to be the identity. The integral factors into two positive-half-line gamma moments and one whole-line Gaussian, giving ')+r'\sqrt\pi\,\Gamma('+L(p+1)+r')\Gamma('+L(p+R(3,2))+r').',T('For the displayed positive definite K, use ')+r'M=K^{-1/2}NK^{-1/2}.'+T('On symmetric two-by-two matrices the Jacobian is ')+r'(\det K)^{-3/2}'+T(', while the determinant weight contributes ')+r'(\det K)^{-'+L(p)+r'}.'],[check('Cholesky absolute Jacobian',jac**2,(4*u*u*w)**2),check('positive matrix determinant',mapping[0]*mapping[1]-mapping[2]**2,u*u*w*w),check('independent cone angular beta normalization',other,s.sqrt(s.pi)*s.gamma(p+1)*s.gamma(p+R(3,2))),truth('precision positive definite',bool(a>0 and det>0)),truth('integrable cone boundary exponent',bool(p>-1))],['Real matrix coordinates; the determinant power uses the positive branch. The precision matrix is positive definite.'],['Cholesky coordinates are bijective on the cone. For diagonal positive S=diag(s1,s2), the map N to SNS has coordinate factors s1 squared, s2 squared and s1*s2, so its three-dimensional Jacobian is (det S)^3. Orthogonal diagonalization preserves symmetric-coordinate volume up to sign, proving the stated congruence formula. All integrands are nonnegative; gamma parameters p+1 and p+3/2 are positive, so Tonelli and the changes of variables are legitimate. An independent identity-matrix route uses z=sqrt(xy)r and an angular beta integral.'],'determinant-weighted-positive-matrix-cone')

@register('elliptic-torsion-sharp-functional','elliptic-Poisson-energy-duality','Find a Poisson witness adapted to an ellipse, use Green identity to turn a nonlinear-looking quotient into Cauchy-Schwarz, and prove equality is attainable.','Distinct from a one-dimensional energy minimum: both the domain geometry and the two-dimensional Poisson equation determine the sharp constant.',[{'a':a,'b':b} for a,b in [(1,2),(1,3),(2,3),(2,4),(2,5),(3,4),(3,5),(3,6),(4,5),(4,6)]],'Poisson-witness-and-energy-Cauchy-Schwarz',('Green identity','variational inequalities'))
def torsion(a,b):
 w=(1-x*x/(a*a)-y*y/(b*b))/(2/(a*a)+2/(b*b));answer=s.pi*a**3*b**3/(4*(a*a+b*b))
 return item(r'\Omega=\{(x,y):x^2/'+L(a*a)+r'+y^2/'+L(b*b)+r'<1\}.'+T('Among nonzero real continuously differentiable functions on the closed ellipse that vanish on its boundary, find the supremum of ')+r'\frac{\left(\iint_\Omega u\,\mathrm dA\right)^2}{\iint_\Omega\left(u_x^2+u_y^2\right)\,\mathrm dA}.',answer,[(2*answer,'omit the quadratic radial average'),(answer/2,'double the Poisson forcing'),(s.pi*a*b/(4*(a*a+b*b)),'omit the squared geometric scaling'),(s.pi*a*a*b*b/(4*(a+b)),'replace squared directional scales by linear ones'),(s.pi*a**3*b**3/(2*(a*a+b*b)),'use area instead of the integral of the Poisson profile')],[T('Choose the boundary-zero Poisson function ')+r'w(x,y)='+L(w)+r',\qquad -\Delta w=1.',T('Green identity and Cauchy-Schwarz give ')+r'\left(\iint_\Omega u\,\mathrm dA\right)^2=\left(\iint_\Omega\nabla u\cdot\nabla w\,\mathrm dA\right)^2\le\left(\iint_\Omega|\nabla u|^2\,\mathrm dA\right)\left(\iint_\Omega|\nabla w|^2\,\mathrm dA\right).',T('Taking u equal to w attains equality. A second integration by parts gives ')+r'\iint_\Omega|\nabla w|^2\,\mathrm dA=\iint_\Omega w\,\mathrm dA.',T('With ')+r'x='+L(a)+r'r\cos\theta,quad y='+L(b)+r'r\sin\theta,'+T(' integrate the profile over the unit disk.')],[check('Poisson witness',-s.diff(w,x,2)-s.diff(w,y,2),1),check('ellipse boundary trace',w.subs({x:a*s.cos(t),y:b*s.sin(t)}),0),check('witness integral by polar coordinates',2*s.pi*a*b/(2/(a*a)+2/(b*b))*s.integrate((1-z*z)*z,(z,0,1)),answer)],['The supremum excludes the zero function; the denominator is positive for every admissible nonzero function. Delta is the sum of the two second partial derivatives.'],['A zero gradient on the connected ellipse would make a function constant; its zero boundary value then makes it zero. Thus all admissible nonzero denominators are positive. Green identity applies with the smooth polynomial witness and continuously differentiable boundary-zero test function, by standard integration by parts. The polynomial witness itself belongs to the admitted class and is nonzero, proving attainment.'],'ellipse-torsion-optimal-integral-over-energy')

@register('support-function-area','convex-support-envelope-area','Recover the actual boundary from a support function, check positive curvature, and use Green area rather than mistaking support distance for polar radius.','A polar-radius area formula is wrong here; the derivative of the support function changes both the boundary and area.',[{'n':n,'m':m} for n,m in [(2,3),(2,4),(2,5),(3,2),(3,4),(3,5),(4,2),(4,3),(4,5),(5,3)]],'support-envelope-and-Green-area',('convex support lines','Green theorem','Fourier orthogonality'))
def support(n,m):
 A=1/(2*(n*n-1));B=1/(3*(m*m-1));h=1+A*s.cos(n*t)+B*s.cos(m*t)
 generic=s.Function('h')(t);bx=generic*s.cos(t)-s.diff(generic,t)*s.sin(t);by=generic*s.sin(t)+s.diff(generic,t)*s.cos(t);zz=s.Symbol('Z');hh=1+A*(zz**n+zz**(-n))/2+B*(zz**m+zz**(-m))/2;constant=s.expand(hh*hh+zz*zz*s.diff(hh,zz)**2).coeff(zz,0)
 answer=s.pi*(1-R(1,8)/(n*n-1)-R(1,18)/(m*m-1))
 return item(T('A convex planar body is the intersection of the half-planes ')+r'x\cos\theta+y\sin\theta\le h(\theta)\quad(0\le\theta\le2\pi),\qquad h(\theta)='+L(h.subs(t,s.Symbol('theta')))+r'.'+T('Find its area.'),answer,[(s.pi*(1+A*A/2+B*B/2),'use the support function as a polar radius'),(s.pi*(1+A*A*(n*n-1)/2+B*B*(m*m-1)/2),'reverse the derivative-square correction'),(s.pi*(1-A*A*n*n/2-B*B*m*m/2),'omit the support-square contributions'),(answer/2,'lose the two sides of the Green area integrand'),(2*answer,'omit the one-half factor in Green area')],[T('The point on the supporting line whose outward normal has angle theta is ')+r'\gamma(\theta)=\bigl(h\cos\theta-h\prime\sin\theta,\ h\sin\theta+h\prime\cos\theta\bigr).',r'h+h\prime\prime=1-\frac12\cos('+L(n)+r'\theta)-\frac13\cos('+L(m)+r'\theta)\ge\frac16>0.',T('This positive radius of curvature makes the support envelope a simple strictly convex boundary. Green theorem and periodic integration by parts yield ')+r'\operatorname{Area}=\frac12\int_0^{2\pi}h(h+h\prime\prime)\,\mathrm d\theta=\frac12\int_0^{2\pi}\bigl(h^2-(h\prime)^2\bigr)\,\mathrm d\theta.',T('Different integer frequencies are orthogonal. Their squared integrals are pi, while the constant term contributes two pi.')],[check('support envelope line identity',bx*s.cos(t)+by*s.sin(t),generic),check('support envelope Green integrand',bx*s.diff(by,t)-by*s.diff(bx,t),generic*(generic+s.diff(generic,t,2))),check('exact Fourier area',s.pi*constant,answer),truth('distinct positive frequencies',bool(n>=2 and m>=2 and n!=m))],['Support function is explicitly defined by the displayed half-plane intersection; theta is the outward-normal angle, not the polar angle.'],['The verified positive curvature-radius bound gives a regular closed strictly convex envelope. Its supporting normal covers the circle once, so it bounds exactly the half-plane intersection. Green theorem is applicable to this smooth boundary. The area computation includes the derivative correction before orthogonality is used.'],'two-frequency-convex-support-envelope-area')

@register('eccentric-annulus-capacity','conformal-capacity-annulus','A doubly connected domain is given through two nonconcentric Apollonius circles; pull it back conformally, prove the sharp energy bound, and construct the attaining function.','Not a direct annular polar integral: the metric distortion cancels only in the Dirichlet energy, and a variational lower bound is required.',[{'m':m,'n':n} for m,n in [(3,2),(4,3),(5,2),(5,3),(5,4),(7,2),(7,3),(7,4),(7,5),(8,3)]],'Mobius-conformal-energy-and-capacity',('conformal Jacobians','Cauchy-Schwarz','boundary energy'))
def capacity(m,n):
 r=1/m;Rr=1/n;answer=2*s.pi/s.log(m/n)
 u,v=s.symbols('u v',real=True);den=(x-1)**2+y*y;wx=(x*(x-1)+y*y)/den;wy=-y/den;J=s.Matrix([wx,wy]).jacobian([x,y])
 return item(T('In the complex plane define ')+r'\Omega=\left\{z:\frac1{'+L(m)+r'}<\left|\frac z{z-1}\right|<\frac1{'+L(n)+r'}\right\}.'+T('For real continuously differentiable functions on the closure, equal to zero on the inner ratio boundary and one on the outer ratio boundary, find the minimum of ')+r'\iint_\Omega |\nabla u|^2\,\mathrm dA.',answer,[(s.pi/s.log(m/n),'omit angular factor two'),(4*s.pi/s.log(m/n),'double the energy'),(2*s.pi*s.log(m/n),'invert the radial energy normalization'),(2*s.pi/s.log(m*n),'replace the ratio of radii by their product'),(2*s.pi/(m-n),'replace logarithmic radial distance by linear distance')],[T('The map ')+r'w=\frac z{z-1}'+T(' is conformal and bijective from the domain onto the circular annulus ')+r'1/'+L(m)+r'<|w|<1/'+L(n)+r'.',T('Under a conformal coordinate change, gradient length squared and area have reciprocal scale factors. Thus Dirichlet energy is unchanged.'),T('For each angle, the boundary difference is one. Weighted Cauchy-Schwarz gives ')+r'1\le\left(\int_{1/'+L(m)+r'}^{1/'+L(n)+r'}\rho\,u_\rho^2\,\mathrm d\rho\right)\ln('+L(m/n)+r').',T('Integrate over angles and discard the nonnegative angular energy. Equality is attained by ')+r'u(z)=\frac{\ln\!\left('+L(m)+r'\left|z/(z-1)\right|\right)}{\ln('+L(m/n)+r')}.'],[check('conformal derivative norm equality',sum(v*v for v in J[:,0]),sum(v*v for v in J[:,1])),check('conformal derivative orthogonality',J[:,0].dot(J[:,1])),check('positive conformal Jacobian',s.factor(J.det()),1/den**2),check('radial witness energy',2*s.pi*s.integrate(1/z,(z,r,Rr))/s.log(m/n)**2,answer)],['The ratio radii satisfy zero < inner < outer < one. The point z=1 is outside the closed domain. The boundary components are disjoint smooth circles.'],['The Mobius map is injective away from its pole and its inverse has no pole on the closed target annulus, since the outer radius is below one. Cauchy-Riemann identities imply the conformal metric cancellation, independently checked through the real Jacobian. The radial lower bound holds for every angle and the displayed smooth pullback attains it with zero angular derivative.'],'Apollonius-annulus-sharp-Dirichlet-energy')

@register('spherical-triangle-vector-area','spherical-vector-area-Stokes','A surface moment over a spherical triangle is recovered from its three great-circle arcs by vector Stokes, requiring edge orientations and angular lengths.','A solid angle gives the integral of one, not the requested coordinate moment; spherical excess alone does not solve this problem.',[{'a':a,'b':b,'c':c} for a,b,c in [(1,1,1),(1,1,2),(1,2,1),(1,2,3),(1,2,2),(1,3,1),(2,2,1),(1,3,2),(2,3,1),(2,3,3)]],'vector-area-boundary-Stokes',('Stokes theorem','great-circle geometry'))
def spherical(a,b,c):
 norm=s.sqrt(a*a+b*b+c*c);A=s.Matrix([1,0,0]);B=s.Matrix([0,1,0]);C=s.Matrix([a,b,c])/norm
 edgeAB=s.pi/2;edgeBC=s.acos(b/norm);edgeCA=s.acos(a/norm)
 answer=s.pi/4-a*edgeBC/(2*s.sqrt(a*a+c*c))-b*edgeCA/(2*s.sqrt(b*b+c*c))
 crossBC=B.cross(C);crossCA=C.cross(A)
 solid=2*s.atan(c/(norm+a+b))
 return item(T('On the unit sphere, let S be the smaller spherical triangle in the positive octant bounded by the shorter great-circle arcs joining ')+r'A=(1,0,0),\quad B=(0,1,0),\quad C=\frac{('+L(a)+','+L(b)+','+L(c)+r')}{'+L(norm)+r'}.'+T('Find ')+r'\iint_S z\,\mathrm dS.',answer,[(solid,'return spherical area instead of its coordinate moment'),(2*answer,'omit the one-half in vector area'),(answer/2,'apply the vector-area factor twice'),(s.pi/4+a*edgeBC/(2*s.sqrt(a*a+c*c))+b*edgeCA/(2*s.sqrt(b*b+c*c)),'reverse the two oblique edge orientations'),(s.pi/4-a*edgeBC/(2*norm)-b*edgeCA/(2*norm),'use chord coefficients without normalizing the edge normals')],[T('With outward unit normal equal to the position vector on the unit sphere, Stokes gives ')+r'\iint_S\mathbf n\,\mathrm dS=\frac12\oint_{\partial S}\mathbf r\times\mathrm d\mathbf r.',T('A positively oriented shorter great-circle arc from U to V contributes ')+r'\arccos(U\cdot V)\,\frac{U\times V}{|U\times V|}.'+T('Use the boundary order A, B, C, A.'),T('The third components of the three unit edge normals are ')+r'1,\quad -\frac{'+L(a)+r'}{'+L(s.sqrt(a*a+c*c))+r'},\quad -\frac{'+L(b)+r'}{'+L(s.sqrt(b*b+c*c))+r'},'+T('and the corresponding arc lengths are ')+L(edgeAB)+r',\ '+L(edgeBC)+r',\ '+L(edgeCA)+'.'],[check('unit C',C.dot(C),1),check('first oblique unit-normal component',crossBC[2]/s.sqrt(crossBC.dot(crossBC)),-a/s.sqrt(a*a+c*c)),check('second oblique unit-normal component',crossCA[2]/s.sqrt(crossCA.dot(crossCA)),-b/s.sqrt(b*b+c*c)),truth('positive boundary orientation',bool(s.det(s.Matrix.hstack(A,B,C))>0))],['The sphere has radius one; all three displayed coordinates of C are positive. Surface orientation is outward.'],['For each constant vector e, the curl of (e cross r)/2 equals e, proving the vector Stokes identity. Parametrize a unit-speed great-circle arc as U cos(s)+V_perp sin(s); its cross product with its derivative is the constant oriented unit edge normal. The determinant of A,B,C is positive, giving the stated outward boundary order. The third component of the resulting vector is precisely the requested surface integral.'],'spherical-triangle-coordinate-moment-from-edges')

@register('saddle-level-band','saddle-coarea-logarithmic-divergence','A thin band around an indefinite quadratic level has a logarithmic excess area; locate the crossing of its zero lines and prove the cutoff shape does not affect the leading coefficient.','Unlike positive-power anisotropic integrability, this is a geometric sublevel asymptotic at a nondegenerate saddle, where a regular-level coarea approximation fails.',[{'a':a,'b':b,'c':c} for a,b,c in [(1,1,1),(1,2,1),(1,3,1),(2,2,1),(2,3,1),(2,4,1),(3,3,2),(1,4,2),(1,5,2),(3,4,2)]],'quadratic-saddle-normal-form-and-log-area',('linear changes of variables','asymptotic comparison'))
def saddle(a,b,c):
 d=a*b+c*c;answer=2/s.sqrt(d);Q=a*x*x+2*c*x*y-b*y*y
 # X=sqrt(a)x+c*y/sqrt(a), Y=sqrt(d/a)y, then u=X+Y,v=X-Y.
 X=s.sqrt(a)*x+c*y/s.sqrt(a);Y=s.sqrt(d/a)*y;uv=s.Matrix([X+Y,X-Y]);jac=uv.jacobian([x,y]).det()
 return item(T('Let A(epsilon) be the planar area of ')+r'\{(x,y):x^2+y^2\le1,\ |'+L(Q)+r'|\le\varepsilon\}.'+T('Find ')+r'\lim_{\varepsilon\downarrow0}\frac{A(\varepsilon)}{\varepsilon\ln(1/\varepsilon)}.',answer,[(1/s.sqrt(d),'count only one pair of quadrants'),(4/s.sqrt(d),'omit the factor two in the hyperbolic coordinate Jacobian'),(2/d,'use determinant rather than its square root'),(2/s.sqrt(a*b),'ignore the mixed term'),(s.pi/s.sqrt(d),'replace the saddle band by an elliptic disk')],[T('Complete the square and then factor the difference of squares: ')+r'X='+L(X)+r',\quad Y='+L(Y)+r',\quad u=X+Y,\quad v=X-Y.',r'Q=uv,\qquad \mathrm dx\,\mathrm dy=\frac{\mathrm du\,\mathrm dv}{'+L(2*s.sqrt(d))+r'}.',T('The transformed disk contains a fixed centered square and lies in another fixed centered square. In a square of half-width R, direct slicing gives ')+r'\operatorname{Area}\{|uv|\le\varepsilon\}=4\varepsilon+4\varepsilon\ln(R^2/\varepsilon)\quad(0<\varepsilon<R^2).',T('Both bounding squares have the same leading coefficient four. Multiply by the constant Jacobian and squeeze.')],[check('quadratic hyperbolic factorization',uv[0]*uv[1],Q),check('absolute hyperbolic Jacobian',jac*jac,4*d),truth('nondegenerate indefinite quadratic',bool(d>0))],['Planar Lebesgue area; epsilon approaches zero through positive values. The disk radius is fixed.'],['The invertible linear map sends the disk to a bounded ellipse containing the origin as an interior point, hence it admits the two square bounds. In each positive quadrant, the band has a rectangle of width epsilon/R and height R plus the hyperbolic region with area integral from epsilon/R to R of epsilon/u. Four quadrants give the exact square formula. The terms involving the fixed square radii disappear after dividing by epsilon*ln(1/epsilon).'],'indefinite-quadratic-thin-band-log-leading-area')

@register('cubic-coefficient-body','root-to-coefficient-Jacobian','A region specified by polynomial roots becomes a coefficient-space volume only after handling the Vandermonde Jacobian and the six-to-one permutation symmetry.','The existing Vandermonde extremum uses a discriminant inequality; this uses the root map as a global change of variables and integrates an ordered chamber.',[{'m':str(m)} for m in [R(-1,2),0,R(1,2),1,2,3,4,5,6,7]],'symmetric-root-map-and-ordered-simplex',('Jacobian determinants','polynomial roots'))
def coefficients(m):
 u,v,w=s.symbols('u v w',positive=True);mapping=s.Matrix([x+y+z,x*y+x*z+y*z,x*y*z]);jac=mapping.jacobian([x,y,z]).det()
 J1=1/((m+1)*(m+2));J2=1/((m+2)*(m+3));answer=s.factor((J1/((2*m+3)*(2*m+4))-J2/((2*m+4)*(2*m+5)))/(3*m+6))
 ordered=s.Matrix([u*v*w,u*v,u]);ordered_jac=ordered.jacobian([u,v,w]).det()
 return item(T('Let Omega consist of real triples (A,B,C) for which ')+r'p(t)=t^3-At^2+Bt-C'+T('has three distinct real roots in the open unit interval. Evaluate ')+r'\iiint_\Omega C^{'+L(m)+r'}\,\mathrm dA\,\mathrm dB\,\mathrm dC.',answer,[(6*answer,'integrate all root permutations without dividing by six'),(answer/6,'divide by six after already ordering the roots'),(1/(6*(m+1)**3),'omit the root-map Jacobian'),(3*answer,'count only cyclic root permutations'),(answer/2,'add a spurious orientation factor')],[T('Order the roots as ')+r'0<x<y<z<1.'+T('On this chamber the coefficient map is bijective and its absolute Jacobian is ')+r'(y-x)(z-x)(z-y).',T('Set ')+r'z=u,\quad y=uv,\quad x=uvw,\qquad 0<u,v,w<1.'+T('The product of the two Jacobians and the weight is ')+r'u^{'+L(3*m+5)+r'}v^{'+L(2*m+2)+r'}w^{'+L(m)+r'}(1-v)(1-w)(1-vw).',T('Integrate in w first: ')+r'\int_0^1w^{'+L(m)+r'}(1-w)(1-vw)\,\mathrm dw='+L(J1)+r'-'+L(J2)+r'v.',T('The remaining two beta integrals are elementary power differences; they produce ')+L((J1/((2*m+3)*(2*m+4))-J2/((2*m+4)*(2*m+5)))/(3*m+6))+'.'],[check('root-coefficient absolute Jacobian',jac*jac,((y-x)*(z-x)*(z-y))**2),check('ordered chamber Jacobian',ordered_jac**2,(u*u*v)**2),check('transformed Vandermonde',((y-x)*(z-x)*(z-y)).subs({x:u*v*w,y:u*v,z:u}),u**3*v*(1-w)*(1-v*w)*(1-v)),check('inner weighted integral',s.integrate(w**m*(1-w)*(1-v*w),(w,0,1)),J1-v*J2),truth('all endpoint powers integrable',bool(m>-1))],['All powers of C use its positive real value; the coefficient body has C>0. Repeated-root boundary points have zero volume and are excluded.'],['Distinct ordered real roots determine exactly one coefficient triple and can be recovered locally by the implicit function theorem since the Vandermonde is nonzero. Thus the map is a diffeomorphism from the ordered chamber onto the stated body. The second substitution maps a unit cube bijectively onto that chamber. Nonnegative integrands permit Tonelli, and the displayed powers are integrable for every listed exponent.'],'ordered-cubic-root-body-weighted-coefficient-volume')

def disk_poly_integral(poly):
 out=0
 for (i,j),c in s.Poly(s.expand(poly),x,y).terms():
  if i%2 or j%2:continue
  p,q=i//2,j//2
  out+=c*s.pi*s.factorial(2*p)*s.factorial(2*q)/(4**(p+q)*s.factorial(p)*s.factorial(q)*s.factorial(p+q+1))
 return s.simplify(out)
@register('Hessian-boundary-determinant','Hessian-determinant-null-Lagrangian','Convert the integral of a nonlinear Hessian determinant to boundary data using a divergence identity; exploit the curvature relation caused by a zero boundary trace.','Different from applying a radial Laplacian repeatedly: the determinant is nonlinear and its interior terms cancel through a null-Lagrangian identity.',[{'n':n,'c':c} for n,c in [(2,1),(3,1),(4,1),(5,1),(6,1),(2,2),(3,2),(4,2),(5,2),(6,2)]],'Hessian-cofactor-divergence-and-boundary-curvature',('divergence theorem','Hessian matrices'))
def hessian_boundary(n,c):
 harmonic=s.expand(s.re((x+s.I*y)**int(n)));u=(1-x*x-y*y)*(1+c*harmonic);Hess=s.hessian(u,(x,y));F=Hess.adjugate()*s.Matrix([s.diff(u,x),s.diff(u,y)]);answer=s.pi*(4+2*c*c)
 return item(r'u(x,y)=(1-x^2-y^2)\left[1+'+L(c)+r'\operatorname{Re}(x+iy)^{'+L(n)+r'}\right].'+T('Find ')+r'\iint_{x^2+y^2\le1}\left(u_{xx}u_{yy}-u_{xy}^2\right)\,\mathrm dx\,\mathrm dy.',answer,[(2*answer,'omit the one-half in the cofactor divergence identity'),(answer/2,'apply that factor twice'),(s.pi*(4+2*n*n*c*c),'differentiate the boundary trace instead of its normal derivative'),(s.pi*(4+c*c),'halve the cosine-square boundary integral'),(s.pi*(4+4*c*c),'double the cosine-square boundary integral')],[T('For any smooth u, the cofactor identity is ')+r'\nabla\cdot\left((\operatorname{cof}D^2u)\nabla u\right)=2\det D^2u.',T('On the unit circle u vanishes. With outward normal n and unit tangent tau, twice differentiating the boundary trace gives ')+r'\tau^{\mathsf T}D^2u\,\tau=u_n.'+T('Therefore the outward cofactor flux is ')+r'u_n^2.',T('For this polynomial, ')+r'u_n=-2\left[1+'+L(c)+r'\cos('+L(n)+r'\theta)\right].'+T('The divergence theorem reduces the integral to ')+r'\frac12\int_0^{2\pi}4\left[1+'+L(c)+r'\cos('+L(n)+r'\theta)\right]^2\,\mathrm d\theta.',T('The cosine mean is zero and its squared integral is pi.')],[check('cofactor divergence identity',s.diff(F[0],x)+s.diff(F[1],y),2*Hess.det()),check('independent direct polynomial disk integral',disk_poly_integral(Hess.det()),answer),check('zero boundary factor',1-s.cos(t)**2-s.sin(t)**2,0)],['The imaginary unit is i, and Re denotes real part. The Hessian determinant uses ordinary real partial derivatives.'],['The polynomial is smooth on the closed disk, so divergence theorem applies directly. Along the unit circle, the second derivative of the boundary parametrization is minus the outward normal; the zero trace therefore gives the stated tangential Hessian relation with positive sign. Since the gradient is normal there, the cofactor flux becomes its squared normal derivative. The independent check expands the entire determinant and integrates its monomials over the disk.'],'disk-Hessian-determinant-boundary-normal-energy')

@register('sphere-quadratic-homogeneity','Gaussian-radial-homogeneity-bridge','Evaluate a nonseparable spherical integral by embedding it into a Gaussian volume integral and using the homogeneity of the radial variable.','The existing Gaussian wedge construction changes the angular region; this keeps the whole sphere and determines the angular density through a radial normalization identity.',[{'a':a,'b':b,'c':c} for a,b,c in [(2,2,2),(2,2,3),(2,3,2),(2,2,4),(2,3,3),(3,2,3),(2,3,5),(3,3,3),(2,4,3),(4,3,2)]],'Gaussian-volume-versus-spherical-coordinates',('positive quadratic forms','Gaussian normalization'))
def sphere_gaussian(a,b,c):
 A=s.Matrix([[a,1,0],[1,b,1],[0,1,c]]);det=A.det();Q=(s.Matrix([x,y,z]).T*A*s.Matrix([x,y,z]))[0];answer=4*s.pi/s.sqrt(det)
 d1=a;d2=b-1/a;d3=c-1/d2
 return item(T('Let S be the unit sphere in three-dimensional Euclidean space. Evaluate ')+r'\iint_S\frac{\mathrm dS}{\left('+L(Q)+r'\right)^{3/2}}.',answer,[(2*s.pi/s.sqrt(det),'use a half-space Gaussian normalization'),(4*s.pi/det,'omit the square root in the volume Jacobian'),(4*s.pi/s.sqrt(a*b*c),'drop the mixed quadratic terms'),(4*s.pi/det**R(3,2),'apply the surface exponent to the determinant'),(s.pi**R(3,2)/s.sqrt(det),'return the Gaussian volume itself'),(8*s.pi/s.sqrt(det),'count both radial signs after already integrating the full sphere'),(4*s.pi*s.sqrt(det),'invert the square-completion volume Jacobian')],[T('The precision matrix is ')+r'A='+L(A)+T('. Its positive pivots show the quadratic form is positive definite. Hence completing squares gives ')+r'\iiint_{\mathbb R^3}e^{-X^{\mathsf T}AX}\,\mathrm dX=\frac{\pi^{3/2}}{\sqrt{\det A}}.',T('In spherical coordinates write ')+r'X=r\omega,\quad |\omega|=1.'+T('For each direction, ')+r'\int_0^\infty r^2e^{-r^2\omega^{\mathsf T}A\omega}\,\mathrm dr=\frac{\sqrt\pi}{4(\omega^{\mathsf T}A\omega)^{3/2}}.',T('Tonelli equates the two evaluations of the positive Gaussian integral. Solve for the requested spherical factor, using ')+r'\det A='+L(det)+'.'],[check('independent LDL pivot determinant',d1*d2*d3,det),truth('positive quadratic pivots',bool(d1>0 and d2>0 and d3>0)),check('radial Gaussian normalization',s.integrate(t*t*s.exp(-t*t),(t,0,s.oo)),s.sqrt(s.pi)/4)],['Surface area measure on the unit sphere; the positive quadratic form never vanishes on it.'],['Positive pivots give an invertible triangular square completion with unit triangular determinant and diagonal product equal to det A. Three one-dimensional Gaussian integrals establish the volume normalization. Nonnegativity permits Tonelli in spherical coordinates. The radial integral follows by scaling and the executed standard Gaussian moment.'],'positive-quadratic-sphere-integral-from-Gaussian-volume')

@register('projective-disk-integral','projective-map-ellipse-Jacobian','Recognize a projective Jacobian, prove the disk image is a bounded ellipse, and extract its area through square completion.','Unlike an affine Gaussian transform, the denominator is a nonconstant Jacobian and the image domain must be recovered from the inverse projective map.',[{'a':str(a),'b':str(b)} for a,b in [(R(1,2),R(1,k)) for k in range(3,13)]],'projective-Jacobian-and-elliptic-image',('Jacobian change of variables','quadratic completion'))
def projective(a,b):
 d=1-a*a-b*b;answer=s.pi/d**R(3,2);den=1+a*x+b*y;mapping=s.Matrix([x/den,y/den]);Q=s.eye(2)-s.Matrix([a,b])*s.Matrix([[a,b]]);center=-Q.inv()*s.Matrix([a,b]);radius=1+(s.Matrix([[a,b]])*Q.inv()*s.Matrix([a,b]))[0]
 return item(r'\iint_{x^2+y^2\le1}\frac{\mathrm dx\,\mathrm dy}{\left('+L(den)+r'\right)^3}.',answer,[(s.pi/s.sqrt(d),'omit the translated ellipse radius factor'),(s.pi/d,'use only one inverse square-root scaling'),(s.pi/d**2,'use an incorrect projective power'),(s.pi/(1+a*a+b*b)**R(3,2),'reverse the quadratic completion sign'),(answer/2,'insert an unnecessary polar one-half factor')],[T('Use the projective coordinates ')+r'u=\frac{x}{'+L(den)+r'},\quad v=\frac{y}{'+L(den)+r'}.'+T('Their Jacobian is exactly the integrand.'),T('The inverse has denominator ')+r'1-('+L(a)+r')u-('+L(b)+r')v.'+T('The disk maps onto the bounded ellipse ')+r'u^2+v^2\le\left(1-('+L(a)+r')u-('+L(b)+r')v\right)^2.',T('Its quadratic matrix is ')+r'Q=I_2-cc^{\mathsf T},\quad c=('+L(a)+','+L(b)+r')^{\mathsf T},\quad\det Q='+L(d)+'.',T('Completing the square gives a centered quadratic level ')+L(1/d)+T('. Therefore its area is ')+r'\pi\frac{'+L(1/d)+r'}{\sqrt{'+L(d)+r'}}.'],[check('projective Jacobian',mapping.jacobian([x,y]).det(),den**-3),check('ellipse determinant',Q.det(),d),check('completed ellipse level',radius,1/d),check('ellipse center equation',Q*center,-s.Matrix([a,b])),truth('positive denominator over disk',bool(a*a+b*b<1))],['Real disk integral; the displayed affine denominator is strictly positive on the closed disk. I_2 is the identity matrix.'],['Cauchy-Schwarz gives a positive denominator on the disk. The projective map is injective where defined and has the displayed inverse. The quadratic matrix Q is positive definite because |c|<1. On the recovered ellipse the inverse denominator cannot vanish: its vanishing together with the ellipse inequality would force u=v=0, a contradiction. Its sign is positive at the image of the origin and hence throughout the connected ellipse. This proves surjectivity onto that ellipse.'],'disk-projective-Jacobian-elliptic-image-area')

@register('three-cylinder-moments','three-cylinder-section-regime','The cross-section changes from a clipped disk to an intact square; locate the transition and integrate the two regimes without treating the intersection as a sphere or two-cylinder solid.','Distinct from a radial or simplex volume: a maximum-type geometric constraint causes a real change of section formula.',[{'m':m} for m in range(7)],'piecewise-cross-section-and-finite-binomial-moments',('spatial intersections','integration by parts'))
def cylinders(m):
 cut=s.sqrt(2)/2;J=sum((-1)**j*s.binomial(m,j)*(1-cut**(2*j+1))/(2*j+1) for j in range(int(m)+1));K=sum((-1)**j*s.binomial(m,j)*(1-cut**(2*j+3))/(2*j+3) for j in range(int(m)+1));tail=(1-cut**(2*m+1))/(2*m+1)-(1-cut**(2*m+3))/(2*m+3);answer=s.simplify(8*(J/(2*m+1)+K+tail))
 u=s.symbols('u',real=True)
 return item(r'\Omega=\{(x,y,z):x^2+y^2\le1,\ y^2+z^2\le1,\ z^2+x^2\le1\}.'+T('Evaluate ')+r'\iiint_\Omega z^{'+L(2*m)+r'}\,\mathrm dx\,\mathrm dy\,\mathrm dz.',answer,[(16/((2*m+1)*(2*m+3)),'omit one of the three cylinder constraints'),(4*s.pi/((2*m+1)*(2*m+3)),'replace the intersection by the unit ball'),(8/(2*m+1),'replace every cross-section by the full square'),(answer/2,'use only nonnegative heights'),(answer/8,'report only one octant'),(answer/4,'use only one quadrant in the horizontal section')],[T('At height z the horizontal section is the unit disk intersected with ')+r'|x|,|y|\le\sqrt{1-z^2}.'+T('For nonnegative heights its area is ')+r'A(z)=\begin{cases}\pi-4\arcsin z+4z\sqrt{1-z^2},&0\le z\le1/\sqrt2,\\4(1-z^2),&1/\sqrt2\le z\le1.\end{cases}',T('Use symmetry in height and integrate ')+r'2\int_0^1z^{'+L(2*m)+r'}A(z)\,\mathrm dz.'+T('An integration by parts cancels the arcsine endpoint against the constant pi term.'),T('Define ')+r'J=\int_{1/\sqrt2}^1(1-u^2)^{'+L(m)+r'}\,\mathrm du='+L(J)+r',\quad K=\int_{1/\sqrt2}^1u^2(1-u^2)^{'+L(m)+r'}\,\mathrm du='+L(K)+'.',T('The substitution ')+r'u=\sqrt{1-z^2}'+T(' in the remaining lower-section terms yields ')+r'8\left(\frac J{'+L(2*m+1)+r'}+K+\int_{1/\sqrt2}^1z^{'+L(2*m)+r'}(1-z^2)\,\mathrm dz\right).'],[check('independent first finite polynomial integral',s.integrate((1-u*u)**m,(u,cut,1)),J),check('independent second finite polynomial integral',s.integrate(u*u*(1-u*u)**m,(u,cut,1)),K),check('square-section tail integral',s.integrate(z**(2*m)*(1-z*z),(z,cut,1)),tail),check('section transition matches',s.pi-4*s.asin(cut)+4*cut*s.sqrt(1-cut*cut),4*(1-cut*cut))],['Volume measure in three-dimensional real space; integer nonnegative moment order. Boundaries have zero volume.'],['When sqrt(1-z squared) exceeds 1/sqrt2, the four disk caps cut by the square sides are disjoint, giving the clipped-disk formula. Above the transition the square lies inside the disk. Symmetry accounts for negative heights. Every subsequent integral is a finite polynomial moment after one integration by parts and the stated substitution, so no improper interchange is involved.'],'triple-Steinmetz-intersection-even-height-moment')

@register('confocal-distance-integral','confocal-coordinate-metric-cancellation','Two distance constraints become independent coordinate bounds, while the product of focal distances cancels the elliptic-coordinate area density.','Unlike ordinary polar integration, both the domain and the metric depend on two fixed foci and the map has a nontrivial angular multiplicity.',[{'a':a,'d':str(d)} for a in range(2,7) for d in [R(1,2),s.sqrt(2)/2]],'elliptic-coordinates-and-focal-distance-Jacobian',('hyperbolic coordinates','changes of variables'))
def confocal(a,d):
 mu,nu=s.symbols('mu nu',real=True);mapping=s.Matrix([s.cosh(mu)*s.cos(nu),s.sinh(mu)*s.sin(nu)]);jac=mapping.jacobian([mu,nu]).det();answer=4*s.asin(d)*s.acosh(a)
 return item(r'r_\pm(x,y)=\sqrt{(x\mp1)^2+y^2},\quad\Omega=\{r_++r_-\le'+L(2*a)+r',\ |r_+-r_-|\le'+L(2*d)+r'\}.'+T('Evaluate ')+r'\iint_\Omega\frac{\mathrm dx\,\mathrm dy}{r_+r_-}.',answer,[(2*s.asin(d)*s.acosh(a),'count only one angular band'),(8*s.asin(d)*s.acosh(a),'count each coordinate image twice'),(4*s.acos(d)*s.acosh(a),'use the complementary angular sectors'),(4*s.asin(d)*a,'replace elliptic radius by its hyperbolic coordinate'),(4*s.asin(d)*s.asinh(a),'invert the wrong hyperbolic function')],[T('Set ')+r'x=\cosh\mu\cos\nu,\quad y=\sinh\mu\sin\nu,\quad \mu\ge0,\ 0\le\nu<2\pi.',r'r_++r_-=2\cosh\mu,\quad |r_+-r_-|=2|\cos\nu|,\quad r_+r_-=\sinh^2\mu+\sin^2\nu.',T('The same expression is the absolute coordinate Jacobian, so the weighted density becomes ')+r'\mathrm d\mu\,\mathrm d\nu.',T('The radial coordinate interval has length ')+r'\operatorname{arccosh}('+L(a)+r')'+T(', and the allowed angular set has total length ')+L(4*s.asin(d))+T('. Their product is the integral.')],[check('elliptic Jacobian',jac,s.sinh(mu)**2+s.sin(nu)**2),check('focal product algebra',(s.cosh(mu)-s.cos(nu))*(s.cosh(mu)+s.cos(nu)),s.sinh(mu)**2+s.sin(nu)**2),truth('nondegenerate focal strip',bool(a>1 and 0<d<1))],['The distance functions are nonnegative principal roots. arccosh is the nonnegative real inverse of cosh on [0,infinity). The restricted domain excludes both foci.'],['Away from the focal segment, elliptic coordinates are one-to-one with mu>0 and a full angular period. The segment has area zero. Squaring the two distances gives (cosh mu minus or plus cos nu) squared, and these quantities are nonnegative, proving the distance formulas. The angular inequality has two bands of total length four arcsin d. Since d<1, the metric denominator stays away from zero at the foci that would otherwise be singular.'],'two-focal-distance-strip-weighted-area')

@register('harmonic-gradient-extremum','harmonic-reproducing-kernel-bound','An interior derivative is an infinite weighted combination of boundary Fourier coefficients; obtain the exact sharp norm and construct the attaining harmonic function.','Different from evaluating a squared harmonic logarithm: this optimizes over all admissible harmonic functions and requires an equality-case construction.',[{'r':str(r)} for r in [R(1,5),R(1,4),R(1,3),R(2,5),R(1,2),R(3,5),R(2,3),R(3,4),R(4,5),R(5,6)]],'Fourier-reproducing-kernel-and-sharp-Cauchy-Schwarz',('harmonic Fourier series','Parseval identity'))
def harmonic_gradient(r):
 q=s.symbols('q',positive=True);series=(1+q)/(1-q)**3;answer=s.sqrt((1+r*r)/(s.pi*(1-r*r)**3))
 return item(T('Let u range over real harmonic functions smooth on the closed unit disk, with ')+r'u(0,0)=0,\quad\int_0^{2\pi}u(\cos\theta,\sin\theta)^2\,\mathrm d\theta\le1.'+T('Find the greatest possible value of ')+r'u_x('+L(r)+r',0).',answer,[(s.sqrt(1/(s.pi*(1-r*r))),'omit the derivative frequency weights'),(s.sqrt((1+r*r)/(2*s.pi*(1-r*r)**3)),'double the boundary cosine normalization'),(s.sqrt(2*(1+r*r)/(s.pi*(1-r*r)**3)),'halve the boundary cosine normalization'),((1+r*r)/(s.pi*(1-r*r)**3),'return the square of the sharp norm'),(s.sqrt((1+r*r)/(s.pi*(1-r*r)**2)),'omit one radial denominator factor')],[T('Write the harmonic expansion ')+r'u(\rho,\theta)=\sum_{n\ge1}\rho^n(a_n\cos n\theta+b_n\sin n\theta).'+T('The zero constant term follows from the value at the center.'),r'\pi\sum_{n\ge1}(a_n^2+b_n^2)\le1,\qquad u_x('+L(r)+r',0)=\sum_{n\ge1}n a_n('+L(r)+r')^{n-1}.',T('Cauchy-Schwarz gives the sharp upper bound ')+r'\left[\frac1\pi\sum_{n\ge1}n^2('+L(r*r)+r')^{n-1}\right]^{1/2}.',r'\sum_{n\ge1}n^2q^{n-1}=\frac{1+q}{(1-q)^3}\quad(0<q<1).'+T('Equality is attained by taking every sine coefficient zero and the cosine coefficients proportional to ')+r'n('+L(r)+r')^{n-1}.'+T('These coefficients decay exponentially, so the maximizing harmonic function is smooth beyond the unit circle.')],[check('weighted geometric generating function',s.diff(q*s.diff(q/(1-q),q),q),series),check('sharp norm squared',answer**2,series.subs(q,r*r)/s.pi),truth('exponential equality coefficients admissible',bool(0<r<1))],['Harmonic means u_xx+u_yy=0. Smoothness on the closed disk ensures the boundary Fourier expansion and its interior derivatives are valid.'],['Parseval gives the coefficient norm and harmonicity extends each boundary Fourier mode by its matching radial power. At a strict interior point the derivative series is absolutely controlled by Cauchy-Schwarz, justifying evaluation. The proposed equality coefficients have exponential decay, define a harmonic function on a larger disk, and can be scaled to boundary norm exactly one. Thus the upper bound is attained in the specified class.'],'sharp-interior-harmonic-derivative-from-boundary-L2')

@register('minimum-enclosing-ellipse','minimum-ellipse-symmetry-active-constraints','Prove a minimum-area enclosing ellipse is centered and axis-aligned before solving a determinant maximization with a changing active constraint.','Different from an ordinary stationary point: the optimization includes the ellipse center, orientation and axes, and symmetry must justify eliminating two of those choices.',[{'a':str(a),'b':str(b)} for a,b in [(1,1),(1,2),(2,3),(R(3,4),1),(R(1,2),1),(R(1,2),R(3,2)),(R(1,3),2),(R(2,3),1),(R(3,2),2),(R(3,4),R(5,4))]],'enclosing-ellipse-symmetry-and-determinant',('positive quadratic forms','global constrained optimization'))
def ellipse(a,b):
 if a*a<R(1,2):p=s.Integer(1);q=(1-a*a)/(b*b)
 elif b*b<R(1,2):q=s.Integer(1);p=(1-b*b)/(a*a)
 else:p=1/(2*a*a);q=1/(2*b*b)
 answer=s.pi/s.sqrt(p*q)
 return item(T('Find the smallest area of a real ellipse containing all eight points ')+r'(\pm1,0),\quad(0,\pm1),\quad(\pm'+L(a)+r',\pm'+L(b)+r'),'+T('where the signs in the last pair are independent.'),answer,[(s.pi*(a*a+b*b),'restrict to the smallest centered circle'),(s.pi*a*b,'use the corner box semiaxes without enclosing its corners'),(4*s.pi*a*b,'double each optimal axis scale'),(s.pi,'ignore the four corner points'),(s.pi*s.sqrt(a*a+b*b),'use the containing-circle radius as its area factor'),(answer/2,'omit the two-axis determinant square root')],[T('Write an ellipse as ')+r'(X-c)^{\mathsf T}Q(X-c)\le1'+T('with Q positive definite. Opposite point pairs imply that recentering and rescaling Q can only reduce the area, so an optimum has center zero.'),T('Reflection symmetry in both axes then allows the off-diagonal entry of Q to be removed: feasibility is preserved and its determinant increases. Write ')+r'Q=\operatorname{diag}(p,q).',r'0<p\le1,\quad0<q\le1,\quad '+L(a*a)+r'p+'+L(b*b)+r'q\le1,\qquad \operatorname{Area}=\frac\pi{\sqrt{pq}}.',T('Maximize the concave logarithm of the product. If neither cap is active, the weighted terms are both one half; otherwise the smaller-coordinate cap is active. In this instance the maximizer is ')+r'p='+L(p)+r',\quad q='+L(q)+'.'],[truth('positive feasible ellipse axes',bool(0<p<=1 and 0<q<=1)),check('corner constraint at optimum',a*a*p+b*b*q,1),truth('unconstrained-or-active-cap classification',bool((p==1 and a*a<=R(1,2)) or (q==1 and b*b<=R(1,2)) or (a*a>=R(1,2) and b*b>=R(1,2)))),check('area squared determinant relation',answer**2*p*q,s.pi**2)],['An ellipse is the filled interior of a positive-definite real quadratic curve. All finite parameter cases have corners outside the unit circle.'],['For opposite points ±v, averaging their quadratic inequalities gives v^TQv+c^TQc<=1. The centered ellipse with matrix Q/(1-c^TQc) contains every point and has no larger area; the denominator is positive because the point set spans the plane. Once centered, the signed corner constraints imply p*a²+q*b²+2|r|ab<=1 for Q off-diagonal r. Dropping r preserves all constraints and increases determinant pq-r². The remaining one-dimensional product on the active line is a concave quadratic, with the stated interior vertex or capped endpoint; this proves global optimality.'],'symmetric-eight-point-minimum-enclosing-ellipse')

@register('optimal-hyperbolic-domain','bathtub-domain-selection','Optimize over measurable planar sets of fixed area; prove that a superlevel set is optimal, recover its hyperbolic boundary from the area constraint, and integrate the selected moment.','Different from optimizing a point or a function derivative: the unknown is an entire domain, and a threshold-exchange argument is needed for global optimality.',[{'q':str(q)} for q in [R(1,10),R(1,8),R(1,6),R(1,5),R(1,4),R(1,3),R(2,5),R(1,2),R(3,5),R(2,3)]],'superlevel-set-exchange-and-area-constraint',('measurable-set optimization','iterated integrals'))
def bathtub(q):
 area=1-q+q*s.log(q);answer=(1-q*q)/4+q*q*s.log(q)/2
 return item(T('Among measurable subsets E of the unit square with area ')+L(area)+T(', find the greatest possible value of ')+r'\iint_E xy\,\mathrm dx\,\mathrm dy.',answer,[(area/4,'replace the selected domain by uniform sampling from the square'),((1-q*q)/4,'omit the hyperbolic lower boundary logarithm'),((1-q*q)/4-q*q*s.log(q)/2,'reverse the logarithm contribution'),(q*area,'replace every selected value by the threshold'),(area,'use the pointwise upper bound as if attained almost everywhere')],[T('Use the threshold region ')+r'E_* =\{(x,y)\in[0,1]^2:xy\ge'+L(q)+r'\}.',r'|E_*|=\int_{'+L(q)+r'}^1\left(1-\frac{'+L(q)+r'}x\right)\,\mathrm dx='+L(area)+'.',T('For any competitor of the same area, ')+r'\iint(\mathbf1_{E_*}-\mathbf1_E)(xy-'+L(q)+r')\,\mathrm dA\ge0.'+T('The integrand is nonnegative on both parts of the symmetric difference, and the threshold terms cancel by equal area.'),r'\iint_{E_*}xy\,\mathrm dA=\int_{'+L(q)+r'}^1\frac x2\left(1-\frac{'+L(q*q)+r'}{x^2}\right)\,\mathrm dx.'],[check('threshold domain exact area',s.integrate(1-q/x,(x,q,1)),area),check('threshold domain exact moment',s.integrate(x*(1-q*q/x**2)/2,(x,q,1)),answer),truth('strict interior threshold',bool(0<q<1))],['Lebesgue area and integrals on the unit square. The indicator of E is one on E and zero elsewhere. Sets differing only on a null set are equivalent.'],['The product xy is at least the threshold on E_* and at most it outside. The exchange inequality therefore proves a global maximum without regularity assumptions on the competitor. The hyperbola xy=q has area zero, so equality determines E_* up to null sets. The two executed elementary integrals verify feasibility and the exact maximum.'],'fixed-area-domain-optimal-product-moment')

@register('optimizer-fourth-envelope-derivative','implicit-optimizer-envelope-jet','A globally convex optimization problem hides an implicit minimizer; use its odd Taylor expansion and the envelope identity to obtain the first nonlinear derivative of the minimum value.','Unlike computing an ordinary Hessian, the requested derivative includes the motion of the optimizer, and differentiating at a fixed point gives zero incorrectly.',[{'a':a,'b':b,'c':c,'p':p,'q':q} for a,b,c,p,q in [(2,2,1,1,0),(2,3,1,1,1),(3,2,1,2,1),(3,3,1,1,-1),(2,4,1,1,2),(4,2,1,2,-1),(3,4,2,1,1),(4,3,2,1,2),(4,4,1,2,1),(3,5,2,2,-1)]],'implicit-minimizer-expansion-and-envelope',('strict convexity','implicit function theorem'))
def envelope(a,b,c,p,q):
 A=s.Matrix([[a,c],[c,b]]);v=s.Matrix([p,q]);w=A.inv()*v;z3=-A.inv()*w.applyfunc(lambda z:z**3);answer=6*sum(z**4 for z in w);path=t*w+t**3*z3
 F=(x**4+y**4)/4+(a*x*x+2*c*x*y+b*y*y)/2-t*(p*x+q*y)
 return item(r'm(t)=\min_{x,y\in\mathbb R}\left\{'+L(F)+r'\right\}.'+T('Find ')+r'm^{(4)}(0).',answer,[(sum(z**4 for z in w),'omit the fourth-derivative factorial'),(24*sum(z**4 for z in w),'differentiate the quartic term while freezing the optimizing path'),(-answer,'reverse the envelope sign'),(6*sum(z*z for z in w),'use the quadratic response in place of the quartic correction'),(6*(p**4+q**4),'ignore the coupled Hessian inverse')],[T('The quadratic matrix ')+r'A='+L(A)+T(' is positive definite. The quartic terms are convex and coercive, so the global minimizer is unique. Its stationarity equation is ')+r'Az+z^{\circ3}=t v,\quad v='+L(v)+r'.',T('The implicit function theorem and odd symmetry give ')+r'z(t)=t w+t^3r+O(t^5),\quad w=A^{-1}v='+L(w)+r',\quad r=-A^{-1}w^{\circ3}.',T('The envelope identity is ')+r'm\prime(t)=-v^{\mathsf T}z(t).'+T('Since A is symmetric, ')+r'-v^{\mathsf T}r=w^{\mathsf T}w^{\circ3}=w_1^4+w_2^4.',T('Integrate the cubic coefficient of the derivative, or differentiate it three times, to obtain ')+r'm^{(4)}(0)=6(w_1^4+w_2^4).'],[check('linear optimizer response',A*w,v),check('cubic optimizer response',A*z3+w.applyfunc(lambda z:z**3),s.zeros(2,1)),check('envelope cubic coefficient',-(v.T*z3)[0],answer/6),check('independent substituted minimum fourth coefficient',s.expand(F.subs({x:path[0],y:path[1]},simultaneous=True)).coeff(t,4)*24,answer),truth('positive definite Hessian',bool(a>0 and A.det()>0))],['The coordinate cube notation z^{circ 3} means cubing each coordinate separately. All derivatives of m are with respect to the real parameter t.'],['The Hessian of the objective in the spatial variables is A plus a nonnegative diagonal matrix, so it is positive definite everywhere. Coercivity gives existence and strict convexity uniqueness of the minimizer. At zero its Hessian A is invertible, so the minimizing branch is analytic locally. Symmetry under simultaneous sign reversal makes it odd. The executed polynomial coefficient check is independent of the envelope coefficient extraction.'],'quartic-convex-minimum-fourth-parameter-derivative')

@register('folded-map-counted-area','real-fold-multiplicity-area','Use the area formula with preimage counts, identify the orientation-changing critical circle, and integrate the absolute Jacobian rather than the signed one.','The polynomial-image winding family counts complex zeros inside one contour; this nonholomorphic real map folds, so local orientation changes must be counted positively.',[{'n':n,'a':str(a)} for n,a in [(2,1),(2,R(1,2)),(3,1),(3,2),(4,1),(4,2),(4,3),(5,2),(5,3),(6,2)]],'area-formula-with-fold-multiplicity',('real Jacobians','finite-to-one maps'))
def folded(n,a):
 zz=x+s.I*y;f=s.expand(zz**int(n)+a*s.conjugate(zz));mapping=s.Matrix([s.re(f),s.im(f)]);jac=s.expand(mapping.jacobian([x,y]).det());cut=(a/n)**(1/(n-1));answer=s.pi*(n-a*a+2*(n-1)*a*a*cut**2/n)
 r=s.symbols('r',positive=True)
 return item(T('For each real pair (u,v), let N(u,v) be the number of distinct complex numbers z in the open unit disk satisfying ')+r'z^{'+L(n)+r'}+'+L(a)+r'\overline z=u+iv.'+T('Evaluate ')+r'\iint_{\mathbb R^2}N(u,v)\,\mathrm du\,\mathrm dv.',answer,[(s.pi*(n-a*a),'integrate the signed Jacobian'),(s.pi*(n+a*a),'add both analytic and anti-analytic area contributions'),(answer/n,'divide by a presumed constant multiplicity'),(2*answer,'count both orientations twice'),(answer/2,'discard one side of the fold')],[T('For the real map ')+r'F(z)=z^{'+L(n)+r'}+'+L(a)+r'\overline z,'+T('the Jacobian is ')+r'J_F='+L(n*n)+r'|z|^{'+L(2*n-2)+r'}-'+L(a*a)+'.',T('The area formula counts all regular preimages positively, so ')+r'\iint N=\iint_{|z|<1}|J_F|\,\mathrm dA=2\pi\int_0^1\left|'+L(n*n)+r'r^{'+L(2*n-2)+r'}-'+L(a*a)+r'\right|r\,\mathrm dr.',T('The sign changes at ')+r'r_0=('+L(a/n)+r')^{'+L(1/(n-1))+r'}.'+T('Split there, or add twice the magnitude of the negative inner contribution to the signed integral: ')+r'\pi('+L(n-a*a)+r')+2\pi\frac{'+L((n-1)*a*a)+r'}{'+L(n)+r'}r_0^2.'],[check('nonholomorphic real Jacobian',jac,n*n*(x*x+y*y)**(n-1)-a*a),check('critical radius',n*n*cut**(2*n-2),a*a),check('independent split absolute-Jacobian integral',2*s.pi*(s.integrate((a*a-n*n*r**(2*n-2))*r,(r,0,cut))+s.integrate((n*n*r**(2*n-2)-a*a)*r,(r,cut,1))),answer),truth('critical circle inside disk',bool(0<a<n))],['Conjugation is complex conjugation; N counts distinct preimages. Critical values and the image of the disk boundary have planar measure zero.'],['The polynomial real map is smooth on the compact disk. Each fiber is finite: eliminate conjugate z using the original equation and its conjugate to obtain a nonzero polynomial of degree n squared in z. The finite-to-one area formula therefore identifies the integral of the counting function with the absolute Jacobian integral. Critical values and boundary images are images of finite smooth algebraic curves and have measure zero, so distinct-versus-algebraic multiplicity on those sets does not alter the integral.'],'nonholomorphic-polynomial-fold-counted-image-area')

@register('Gaussian-entropy-variational','continuous-entropy-Gaussian-moment','Identify a Gaussian that matches all prescribed moments, then use a pointwise convex inequality to prove it is the unique minimizer of a nonlinear integral over all densities.','Different from the finite log-sum-exp stationary minimum: the variable is a density on an unbounded plane, and the moment constraints eliminate a quadratic log-density term.',[{'a':a,'b':b,'c':c} for a,b,c in [(2,2,1),(2,3,1),(2,4,1),(3,3,1),(3,4,2),(4,4,1),(4,5,2),(2,5,1),(3,5,2),(4,6,3)]],'relative-entropy-convexity-and-Gaussian-matching',('probability densities','Gaussian integrals','convexity'))
def entropy_density(a,b,c):
 S=s.Matrix([[a,c],[c,b]]);det=S.det();answer=-s.log(2*s.pi)-1-s.log(det)/2
 return item(T('Let rho range over probability densities on the real plane with mean zero, finite entropy integral, and covariance matrix ')+r'\Sigma='+L(S)+r'.'+T('Find the minimum of ')+r'\iint_{\mathbb R^2}\rho(x,y)\ln\rho(x,y)\,\mathrm dx\,\mathrm dy,'+T('using the convention that zero times its logarithm is zero.'),answer,[(-s.log(2*s.pi)-1+s.log(det)/2,'reverse the covariance determinant scaling'),(-s.log(2*s.pi)-s.log(det)/2,'omit the mean quadratic contribution'),(-s.log(2*s.pi)-1-s.log(det),'use the determinant rather than its square root in the Gaussian normalization'),(s.log(2*s.pi)+1+s.log(det)/2,'return entropy rather than its negative'),(-s.log(s.pi)-1-s.log(det)/2,'use the wrong Gaussian normalization')],[T('Let g be the centered Gaussian with the specified covariance: ')+r'g(X)=\frac{\exp(-X^{\mathsf T}\Sigma^{-1}X/2)}{2\pi\sqrt{\det\Sigma}}.',T('The pointwise inequality ')+r'h\ln h-h+1\ge0\quad(h\ge0)'+T('with ')+r'h=\rho/g'+T('gives ')+r'\iint\rho\ln(\rho/g)\,\mathrm dX\ge0.',T('The moment constraints imply ')+r'\iint\rho\,X^{\mathsf T}\Sigma^{-1}X\,\mathrm dX=\operatorname{tr}(\Sigma^{-1}\Sigma)=2.',T('Thus the integral of rho times ln g is fixed, equal to ')+r'-\ln(2\pi)-\frac12\ln\det\Sigma-1.'+T('The Gaussian attains this lower bound, and the strict equality condition makes it the unique minimizer up to null sets.')],[check('covariance quadratic expectation',s.trace(S.inv()*S),2),truth('positive covariance',bool(a>0 and det>0)),check('scalar convexity second derivative',s.diff(t*s.log(t)-t+1,t,2),1/t)],['A probability density is nonnegative and integrates to one. Mean and covariance are the ordinary first and second moments. Admissible densities have a finite real entropy integral.'],['The Gaussian is positive, normalizable and has the required covariance by an invertible linear transformation of independent standard Gaussians. The scalar convexity inequality follows from its derivative ln h and its minimum at one, extended continuously at zero. Applying it with Gaussian measure yields the relative-entropy bound; finite entropy and finite quadratic moments make the relevant terms well defined. Equality forces rho/g=1 almost everywhere.'],'fixed-covariance-density-minimum-negative-entropy')

@register('Vandermonde-Gram-integral','determinantal-multiple-integration','Turn a coupled product of all pairwise differences into two determinants, integrate their permutation expansion, and evaluate a Cauchy moment determinant.','Unlike root-to-coefficient volume, the squared Vandermonde is integrated over a full cube and its antisymmetric expansion reduces a high-dimensional integral to a Gram determinant.',[{'n':n,'a':a} for n,a in [(3,0),(3,1),(3,2),(4,0),(4,1),(4,2),(5,0),(5,1),(6,0),(6,1)]],'Andreief-expansion-and-Cauchy-determinant',('determinant expansion','finite Fubini'))
def vandermonde(n,a):
 nn=int(n);G=s.Matrix(nn,nn,lambda i,j:1/(a+i+j+1));numer=s.prod((j-i)**2 for i in range(nn) for j in range(i+1,nn));denom=s.prod(a+i+j+1 for i in range(nn) for j in range(nn));answer=s.factorial(n)*numer/denom
 return item(r'\int_{[0,1]^{'+L(n)+r'}}\left(\prod_{i=1}^{'+L(n)+r'}x_i^{'+L(a)+r'}\right)\left(\prod_{1\le i<j\le'+L(n)+r'}(x_i-x_j)^2\right)\,\mathrm dx_1\cdots\mathrm dx_{'+L(n)+r'}.',answer,[(answer/s.factorial(n),'omit the permutation multiplicity'),(answer*s.factorial(n),'count the same permutations twice'),(s.factorial(n)/denom,'omit the Vandermonde factors in the Cauchy determinant'),(numer/denom**2,'square the moment denominator once too often'),(1/(a+1)**n,'omit the pairwise-difference coupling')],[T('The Vandermonde product is the determinant of the monomial matrix. Expand both determinant factors into permutations and integrate each product separately. Relabeling one permutation leaves ')+r'I='+L(s.factorial(n))+r'\det\left[\int_0^1x^{'+L(a)+r'+i+j}\,\mathrm dx\right]_{i,j=0}^{'+L(n-1)+r'}.',r'I='+L(s.factorial(n))+r'\det\left[\frac1{'+L(a+1)+r'+i+j}\right]_{i,j=0}^{'+L(n-1)+r'}.',T('For this Cauchy matrix, multiplying by all denominators yields a polynomial alternating in the row parameters and separately in the column parameters. Its degree and leading coefficient give ')+r'\det G=\frac{\prod_{0\le i<j<'+L(n)+r'}(j-i)^2}{\prod_{i,j=0}^{'+L(n-1)+r'}('+L(a+1)+r'+i+j)}.'],[check('independent exact determinant by elimination',G.det(),numer/denom),check('first moment integral',s.integrate(x**a,(x,0,1)),G[0,0]),check('last moment integral',s.integrate(x**(a+2*n-2),(x,0,1)),G[-1,-1]),truth('finite moments and distinct Cauchy parameters',bool(n>=2 and a>=0))],['All integration coordinates range independently from zero to one. An exponent zero contributes the constant one, including at endpoints by continuity.'],['The integrand is a bounded polynomial, so finite determinant expansions and Fubini need no convergence qualification. For every fixed first permutation, relabeling the integration coordinates yields the same determinant of moments, producing exactly n! copies. The Cauchy identity is an algebraic theorem whose alternating-polynomial proof is stated; exact Gaussian elimination independently checks its value for every finite matrix in the declared domain.'],'squared-Vandermonde-cube-integral-Gram-determinant')

def exact_hull_volume(points):
 """Independent finite rational convex-hull volume, exhaustive supporting planes."""
 import math
 from itertools import combinations
 scale=s.ilcm(*[s.denom(v) for p in points for v in p]);P=sorted(set(tuple(int(scale*v) for v in p) for p in points))
 cross=lambda a,b:(a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0])
 sub=lambda a,b:tuple(a[i]-b[i] for i in range(3));dot=lambda a,b:sum(a[i]*b[i] for i in range(3))
 planes={}
 for p,q,r in combinations(P,3):
  normal=cross(sub(q,p),sub(r,p))
  if normal==(0,0,0):continue
  d=dot(normal,p);g=math.gcd(*normal,d);normal=tuple(v//g for v in normal);d//=g
  first=next(v for v in normal if v)
  if first<0:normal=tuple(-v for v in normal);d=-d
  key=normal+(d,)
  if key in planes:continue
  signs=[dot(normal,v)-d for v in P]
  if not(all(v<=0 for v in signs) or all(v>=0 for v in signs)):continue
  planes[key]=[v for v,k in zip(P,signs) if k==0]
 total=0
 for key,face in planes.items():
  drop=max(range(3),key=lambda k:abs(key[k]));axes=[k for k in range(3) if k!=drop]
  pts=sorted(face,key=lambda p:(p[axes[0]],p[axes[1]]))
  orient=lambda p,q,r:(q[axes[0]]-p[axes[0]])*(r[axes[1]]-p[axes[1]])-(q[axes[1]]-p[axes[1]])*(r[axes[0]]-p[axes[0]])
  lower=[];upper=[]
  for v in pts:
   while len(lower)>=2 and orient(lower[-2],lower[-1],v)<=0:lower.pop()
   lower.append(v)
  for v in reversed(pts):
   while len(upper)>=2 and orient(upper[-2],upper[-1],v)<=0:upper.pop()
   upper.append(v)
  hull=lower[:-1]+upper[:-1]
  for i in range(1,len(hull)-1):total+=abs(dot(hull[0],cross(hull[i],hull[i+1])))
 return R(total,6*int(scale)**3)

@register('zonotope-volume','zonotope-mixed-determinant-volume','A many-to-one image of a five-dimensional cube fills a three-dimensional zonotope; ordinary rectangular Jacobians do not apply, so use the mixed determinant decomposition and its sign cases.','Different from a single linear change of variables: five generators exceed the spatial dimension and all independent triples contribute volume.',[{'a':str(a),'b':str(b)} for a,b in [(R(1,2),R(1,3)),(R(1,2),2),(2,R(1,3)),(2,3),(2,4),(R(3,2),R(2,3)),(R(2,3),R(3,4)),(R(3,2),R(5,2)),(R(5,2),R(7,2)),(3,R(1,2))]],'zonotope-extrusion-and-minor-decomposition',('convex geometry','determinants'))
def zonotope(a,b):
 from itertools import product,combinations
 V=[s.Matrix(v) for v in [(1,0,0),(0,1,0),(0,0,1),(a,1,1),(1,b,1)]];minors=[s.det(s.Matrix.hstack(*vs)) for vs in combinations(V,3)];answer=sum(abs(v) for v in minors)
 points=[tuple(sum((e*v for e,v in zip(bits,V)),s.zeros(3,1))) for bits in product((0,1),repeat=5)];volume=exact_hull_volume(points)
 return item(r'v_1=(1,0,0),\ v_2=(0,1,0),\ v_3=(0,0,1),\ v_4=('+L(a)+r',1,1),\ v_5=(1,'+L(b)+r',1).'+T('Find the three-dimensional volume of ')+r'Z=\left\{\sum_{j=1}^5t_jv_j:0\le t_j\le1\right\}.',answer,[(abs(sum(minors)),'sum oriented determinants before taking the absolute value'),(s.Integer(1),'keep only the first basis parallelepiped'),(sum(v*v for v in minors),'square the triple determinants'),(2*answer,'count both orientations of every triple'),(answer/6,'insert a simplex factor although the pieces are parallelepipeds')],[T('Adding a segment to a convex body increases volume by its length times the area of the orthogonal projection onto the perpendicular plane. This follows by slicing along parallel lines.'),T('For a planar zonotope, repeating the same extrusion argument gives its area as the sum of absolute two-generator determinants. Applying this to each added segment in space yields ')+r'\operatorname{Vol}(Z)=\sum_{1\le i<j<k\le5}|\det(v_i,v_j,v_k)|.',T('The ten oriented triple determinants in lexicographic order are ')+r'('+','.join(L(v) for v in minors)+r').'+T('Take absolute values individually and add.')],[check('independent exhaustive rational convex-hull volume',volume,answer),truth('spatial span has rank three',s.Matrix.hstack(*V).rank()==3)],['Z is the full Minkowski sum of the five closed line segments, with overlaps counted only once. Volume is ordinary three-dimensional Lebesgue volume.'],['For a convex body, each line parallel to an added segment meets the body in an interval or the empty set. Minkowski addition extends every nonempty interval by the segment length; Fubini gives the extrusion formula. Induction in the plane and then in space gives the absolute-minor sum, with each triple introduced once. The independent finite verifier enumerates all 32 subset-sum vertices, exhaustively identifies supporting planes by exact integer signs, constructs each facet convex polygon, and sums exact tetrahedron volumes. No floating-point hull discovery is used.'],'five-generator-spatial-zonotope-exact-volume')
